import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUIDv7 primary key generated by the database (native `uuidv7()` needs PostgreSQL 18+). */
export const primaryKey = () => uuid("id").primaryKey().default(sql`uuidv7()`);

/** A UTC `timestamptz` column. Values are exchanged with the app as `Date`. */
export const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const createdAt = () => timestamptz("created_at").notNull().defaultNow();

/** Kept current by the `set_updated_at` trigger, not by application code. */
export const updatedAt = () => timestamptz("updated_at").notNull().defaultNow();
